insert into public.words (word, phonetic, meanings, sort_order) values
('set apart', '/sɛt əˈpɑːrt/', '[{"pos":"동사구","definition":"차별화하다, 눈에 띄게 하다, (특정 목적을 위해) 따로 떼어 두다","toeic_note":"타사 제품과 우리 제품을 ''차별화''하는 맥락으로 비즈니스 지문에 자주 등장.","etymology":"Root: ''set''(두다) + ''apart''(따로) -> 다른 것들로부터 따로 떼어놓아 돋보이게 함.","synonyms":"distinguish(구별하다), differentiate(차별화하다), separate(분리하다)","examples":[{"en":"Quality service is what sets our company apart from the competition.","ko":"품질 좋은 서비스가 우리 회사를 경쟁사와 차별화해 주는 것입니다."}]}]'::jsonb, 1),
('leading', '/ˈliːdɪŋ/', '[{"pos":"형용사","definition":"선두적인, 선도적인, 주요한","toeic_note":"a leading manufacturer(선두 제조업체) 패턴 기억 필수.","etymology":"Root: ''lead''(이끌다) + ''-ing''(현재분사/형용사형 접미사) -> 남보다 앞서서 이끄는.","synonyms":"foremost(으뜸가는), prominent(유명한), top-tier(일류의)","examples":[{"en":"He is a leading expert in the field of renewable energy.","ko":"그는 재생 에너지 분야의 선도적인 전문가입니다."}]}]'::jsonb, 2),
('outset', '/ˈaʊtset/', '[{"pos":"명사","definition":"시작, 발단","toeic_note":"주로 ''from the outset(처음부터)'' 관용구로 출제됨.","etymology":"Prefix: ''out-''(밖으로) + ''set''(두다/나서다) -> 밖으로 나서는 지점, 즉 시작점.","synonyms":"beginning(시작), commencement(시작), start(출발)","examples":[{"en":"We made it clear from the outset that we needed a flexible schedule.","ko":"우리는 처음부터 유연한 일정이 필요하다는 점을 분명히 했습니다."}]}]'::jsonb, 3),
('cite', '/saɪt/', '[{"pos":"동사","definition":"인용하다, (이유·예로) 언급하다","toeic_note":"보고서나 기사 지문에서 통계나 전문가의 말을 인용할 때 사용.","etymology":"Root: Latin ''citare''(부르다, 움직이게 하다) -> 증인이나 말을 법정으로 불러내듯 인용함.","synonyms":"quote(인용하다), mention(언급하다), specify(명시하다)","examples":[{"en":"The CEO cited rising fuel costs as the main reason for the price hike.","ko":"CEO는 가격 인상의 주된 원인으로 상승하는 연료비를 언급했습니다."}]}]'::jsonb, 4),
('refrain', '/rɪˈfreɪn/', '[{"pos":"동사","definition":"자제하다, 삼가다","toeic_note":"주로 ''refrain from -ing(~하는 것을 자제하다)'' 전치사 from과 함께 출제.","etymology":"Prefix: ''re-''(뒤로) + Root: Latin ''frenum''(고삐) -> 고삐를 뒤로 당겨 멈추게 함.","synonyms":"abstain(자제하다), avoid(피하다), desist(그만두다)","examples":[{"en":"Please refrain from using mobile phones during the performance.","ko":"공연 중에는 휴대전화 사용을 자제해 주시기 바랍니다."}]}]'::jsonb, 5),
('feature', '/ˈfiːtʃər/', '[{"pos":"명사","definition":"특징, 기능, 특별 기사","toeic_note":"제품의 ''features(기능)''나 잡지의 ''special feature(특별 기사)''로 자주 나옴.","etymology":"Root: Latin ''factura''(만듦새) -> 물건의 겉모양이나 특별한 만듦새.","synonyms":"characteristic(특징), trait(특성), aspect(측면)","examples":[{"en":"The new smartphone has several unique features.","ko":"그 새 스마트폰은 몇 가지 독특한 기능을 가지고 있습니다."}]},{"pos":"동사","definition":"특징으로 삼다, 특별히 포함하다","toeic_note":"The concert will feature... (콘서트에는 ~가 출연할 것이다) 패턴 주의.","etymology":"Root: ''feature''(특징) -> 어떤 것을 주요 특징으로 내세우다.","synonyms":"highlight(강조하다), showcase(선보이다), include(포함하다)","examples":[{"en":"The upcoming exhibition will feature works by local artists.","ko":"다가오는 전시회는 지역 예술가들의 작품을 특별히 선보일 예정입니다."}]}]'::jsonb, 6),
('shareholder', '/ˈʃerhoʊldər/', '[{"pos":"명사","definition":"주주","toeic_note":"shareholder meeting(주주 총회)은 토익 파트 7 빈출 주제.","etymology":"Root: ''share''(주식/지분) + ''holder''(보유자) -> 기업의 지분을 가진 사람.","synonyms":"stockholder(주주), investor(투자자)","examples":[{"en":"The board of directors is accountable to the shareholders.","ko":"이사회는 주주들에 대해 책임을 집니다."}]}]'::jsonb, 7),
('commuter', '/kəˈmjuːtər/', '[{"pos":"명사","definition":"통근자","toeic_note":"교통 정체나 대중교통 관련 지문에서 commuter train/bus 등으로 등장.","etymology":"Root: ''commute''(통근하다/바꾸다) + ''-er''(사람) -> 정기적으로 장소를 바꿔 이동하는 사람.","synonyms":"traveler(여객), daily traveler(정기 이용객)","examples":[{"en":"The delay in the subway caused a lot of stress for commuters.","ko":"지하철 연착은 통근자들에게 많은 스트레스를 주었습니다."}]}]'::jsonb, 8),
('desperate', '/ˈdespərət/', '[{"pos":"형용사","definition":"절실한, 간절한, 필사적인","toeic_note":"인력 충원이 ''절실한(desperate need for staff)'' 상황 묘사 시 사용.","etymology":"Root: Latin ''desperatus''(희망을 버린) -> 희망이 없어 보일 정도로 절박하고 필사적인.","synonyms":"dire(대단히 심각한), urgent(긴급한), frantic(발광한, 필사적인)","examples":[{"en":"The company is in desperate need of a new marketing strategy.","ko":"그 회사는 새로운 마케팅 전략이 절실히 필요한 상황입니다."}]}]'::jsonb, 9),
('mural', '/ˈmjʊrəl/', '[{"pos":"명사","definition":"벽화","toeic_note":"파트 1 사진 묘사에서 벽에 그려진 그림을 설명할 때 등장.","etymology":"Root: Latin ''murus''(벽) -> 벽에 직접 그린 그림.","synonyms":"wall painting(벽화), fresco(프레스코 화)","examples":[{"en":"The artist is painting a colorful mural on the side of the building.","ko":"예술가가 건물 측면에 형형색색의 벽화를 그리고 있습니다."}]}]'::jsonb, 10),
('commission', '/kəˈmɪʃn/', '[{"pos":"명사","definition":"위원회, 수수료, 의뢰","toeic_note":"판매 실적에 따른 ''수수료(sales commission)'' 맥락 확인.","etymology":"Prefix: ''com-''(함께) + Root: ''mit''(보내다) -> 일을 완수하도록 권한을 함께 보내 위임함.","synonyms":"fee(수수료), percentage(수수료), committee(위원회)","examples":[{"en":"The real estate agent earns a 5% commission on every house sold.","ko":"부동산 중개인은 집이 팔릴 때마다 5%의 수수료를 받습니다."}]},{"pos":"동사","definition":"의뢰하다, 주문하다","toeic_note":"건축이나 예술 작품을 ''의뢰(commission a project)''할 때 쓰임.","etymology":"Root: ''commission''(위임) -> 특정한 과업을 맡기다.","synonyms":"order(주문하다), request(요청하다), contract(계약하다)","examples":[{"en":"The company commissioned a local architect to design the new office.","ko":"회사는 지역 건축가에게 새 사무실 설계를 의뢰했습니다."}]}]'::jsonb, 11),
('approval', '/əˈpruːvl/', '[{"pos":"명사","definition":"승인, 허가, 찬성","toeic_note":"get final approval(최종 승인을 받다), subject to approval(승인 대상인) 패턴 빈출.","etymology":"Prefix: ''ap-''(~로) + Root: ''prov''(입증하다/테스트하다) -> 좋다는 것이 입증되어 허가함.","synonyms":"authorization(재가, 인가), permission(허락, 승인), consent(동의)","examples":[{"en":"We are waiting for the manager''s approval before proceeding with the plan.","ko":"우리는 계획을 진행하기 전에 매니저의 승인을 기다리고 있습니다."}]}]'::jsonb, 12),
('pitch', '/pɪtʃ/', '[{"pos":"명사","definition":"권유, 홍보, (음의) 높낮이","toeic_note":"sales pitch(영업 홍보/권유) 표현은 무조건 암기.","etymology":"Root: Old English ''pic''(던지다) -> 상대를 향해 아이디어를 ''던지는'' 행위에서 유래.","synonyms":"proposal(제안), presentation(발표), promotion(홍보)","examples":[{"en":"The marketing team gave an excellent sales pitch to the investors.","ko":"마케팅 팀은 투자자들에게 훌륭한 영업 홍보를 했습니다."}]},{"pos":"동사","definition":"홍보하다, 내던지다","toeic_note":"아이디어를 ''내놓다/홍보하다''는 의미로 비즈니스 미팅에서 사용.","etymology":"Root: ''pitch''(던지다) -> 공을 던지듯 적극적으로 아이디어를 제시함.","synonyms":"present(제시하다), propose(제안하다), cast(던지다)","examples":[{"en":"She pitched her idea for a new app during the meeting.","ko":"그녀는 회의 중에 새로운 앱에 대한 아이디어를 제안했습니다."}]}]'::jsonb, 13),
('in suspense', '/ɪn səˈspens/', '[{"pos":"형용사구","definition":"불안한, 긴장된, 마음을 졸이는","toeic_note":"결과 발표를 기다리며 ''마음을 졸이는'' 상태 묘사.","etymology":"Prefix: ''sub-''(아래) + Root: ''pend''(매달다) -> 아래에 대롱대롱 매달려 있어 불안한 상태.","synonyms":"apprehensive(걱정되는), anxious(불안해하는), on edge(안절부절못하는)","examples":[{"en":"The audience was kept in suspense until the very end of the movie.","ko":"관객들은 영화가 끝날 때까지 긴장을 늦추지 못했습니다."}]}]'::jsonb, 14),
('convince', '/kənˈvɪns/', '[{"pos":"동사","definition":"확신시키다, 납득시키다, 설득하다","toeic_note":"convince A of B(A에게 B를 확신시키다), convince A to do(A에게 ~하도록 설득하다).","etymology":"Prefix: ''con-''(완전히) + Root: Latin ''vincere''(이기다) -> 말싸움에서 완전히 이겨 상대가 믿게 만듦.","synonyms":"persuade(설득하다), assure(장담하다, 확언하다), satisfy(납득시키다)","examples":[{"en":"We need to convince the clients that our product is the best choice.","ko":"우리는 우리 제품이 최선의 선택이라는 점을 고객들에게 납득시켜야 합니다."}]}]'::jsonb, 15),
('infusion', '/ɪnˈfjuːʒn/', '[{"pos":"명사","definition":"투입, 주입","toeic_note":"capital infusion(자금 투입)은 사업 확장이나 위기 극복 지문에서 자주 나옴.","etymology":"Prefix: ''in-''(안으로) + Root: Latin ''fundere''(붓다) -> 안으로 무언가를 쏟아 붓는 것.","synonyms":"injection(주입), introduction(도입), addition(추가)","examples":[{"en":"A fresh infusion of capital saved the company from bankruptcy.","ko":"새로운 자금 투입이 회사를 파산 위기에서 구했습니다."}]}]'::jsonb, 16),
('wing', '/wɪŋ/', '[{"pos":"명사","definition":"별관, 동, 날개","toeic_note":"본관(main building)과 대비되는 ''별관''의 의미로 자주 출제.","etymology":"Root: Old Norse ''vaengr''(날개) -> 건물의 중심부에서 날개처럼 뻗어 나온 부분.","synonyms":"annex(별관), extension(증축 건물), section(구역)","examples":[{"en":"The accounting department is located in the west wing of the building.","ko":"회계 부서는 건물의 서관(별관)에 위치해 있습니다."}]}]'::jsonb, 17),
('presence', '/ˈprezns/', '[{"pos":"명사","definition":"참석, 존재(감), 영향력","toeic_note":"request the presence of (~의 참석을 요청하다) 공식 초대장 문구 주의.","etymology":"Prefix: ''pre-''(앞에) + Root: Latin ''esse''(있다) -> 누군가나 무언가가 바로 앞에 있음.","synonyms":"attendance(참석), existence(존재), appearance(출현)","examples":[{"en":"Your presence is requested at the annual charity gala.","ko":"연례 자선 가라 행사에 귀하의 참석을 요청드립니다."}]}]'::jsonb, 18),
('on hand', '/ɑːn hænd/', '[{"pos":"형용사구","definition":"자리에 있는, 준비되어 있는, 이용 가능한","toeic_note":"staff on hand(대기 중인 직원) 표현은 서비스 관련 지문 단골.","etymology":"Idiom: ''on''(위에) + ''hand''(손) -> 바로 손 닿는 곳에 대기 중인 상태.","synonyms":"available(이용 가능한), ready(준비된), accessible(접근 가능한)","examples":[{"en":"Customer service representatives are on hand to answer your questions.","ko":"고객 서비스 담당자들이 귀하의 질문에 답하기 위해 자리에 대기하고 있습니다."}]}]'::jsonb, 19),
('mingle', '/ˈmɪŋɡl/', '[{"pos":"동사","definition":"어울리다, 섞이다","toeic_note":"사교 행사나 파티 지문에서 사람들과 대화하며 어울리는 맥락.","etymology":"Root: Germanic ''mengan''(섞다) -> 여러 부류의 사람들이 한데 어우러지는 것.","synonyms":"socialize(어울리다), interact(교류하다), blend(섞이다)","examples":[{"en":"The cocktail hour is a great time for attendees to mingle.","ko":"칵테일 시간은 참석자들이 서로 어울리기에 아주 좋은 시간입니다."}]}]'::jsonb, 20),
('crowd', '/kraʊd/', '[{"pos":"명사","definition":"사람들, 군중, 무리","toeic_note":"행사장이나 관광지의 ''인파''를 지칭할 때 사용.","etymology":"Root: Old English ''crudan''(밀치다) -> 사람들이 서로 밀칠 정도로 모여 있는 상태.","synonyms":"throng(인파), gathering(모임), multitude(다수)","examples":[{"en":"A huge crowd waited outside the store for the grand opening.","ko":"대규모 인파가 매장 밖에서 개업식을 기다렸습니다."}]}]'::jsonb, 21),
('invaluable', '/ɪnˈvæljuəbl/', '[{"pos":"형용사","definition":"귀중한, 매우 유용한","toeic_note":"valuable보다 더 강조된 의미임에 주의 (반의어가 아님!).","etymology":"Prefix: ''in-''(강조) + Root: ''value''(가치) -> 가치를 매길 수 없을 정도로 매우 귀중한.","synonyms":"priceless(값을 매길 수 없는), precious(귀중한), indispensable(없어서는 안 될)","examples":[{"en":"Her experience was invaluable during the complex negotiations.","ko":"그녀의 경험은 복잡한 협상 과정에서 매우 귀중했습니다."}]}]'::jsonb, 22),
('testimonial', '/ˌtestɪˈmoʊniəl/', '[{"pos":"명사","definition":"추천글, 후기, 감사장","toeic_note":"제품 웹사이트의 ''customer testimonials(고객 후기)'' 섹션 관련 지문 빈출.","etymology":"Root: Latin ''testimonium''(증거) -> 제품의 품질을 증명해 주는 글.","synonyms":"recommendation(추천), endorsement(지지), review(후기)","examples":[{"en":"We updated our website with new customer testimonials.","ko":"우리는 새로운 고객 추천글들로 웹사이트를 업데이트했습니다."}]}]'::jsonb, 23),
('make the most of', '/meɪk ðə moʊst ʌv/', '[{"pos":"동사구","definition":"~을 최대한으로 활용하다, 이용하다","toeic_note":"자원이나 기회를 ''최대한 활용''하라는 조언이나 광고 문구에 등장.","etymology":"Idiom: ''make''(만들다) + ''the most''(최대한) -> 주어진 것에서 최상의 결과를 끌어냄.","synonyms":"utilize(이용하다), maximize(극대화하다), exploit(활용하다)","examples":[{"en":"Employees should make the most of the training opportunities provided.","ko":"직원들은 제공된 교육 기회를 최대한 활용해야 합니다."}]}]'::jsonb, 24),
('ergonomic', '/ˌɜːrɡəˈnɑːmɪk/', '[{"pos":"형용사","definition":"인체공학적인","toeic_note":"사무용 가구(의자, 책상)나 도구의 디자인을 설명할 때 필수 단어.","etymology":"Root: Greek ''ergon''(일) + ''nomos''(법칙) -> 업무 효율과 편안함을 위한 설계 법칙.","synonyms":"user-friendly(사용자 친화적인), comfortable(편안한)","examples":[{"en":"The company invested in ergonomic chairs to improve employee comfort.","ko":"회사는 직원의 편안함을 개선하기 위해 인체공학적 의자에 투자했습니다."}]}]'::jsonb, 25),
('strive', '/straɪv/', '[{"pos":"동사","definition":"노력하다, 분투하다","toeic_note":"주로 ''strive to do(~하려고 노력하다)'' 또는 ''strive for (~을 위해 노력하다)''로 출제.","etymology":"Root: Old French ''estriver''(싸우다/다투다) -> 목표를 달성하기 위해 격렬하게 노력함.","synonyms":"endeavor(노력하다), attempt(시도하다), struggle(분투하다)","examples":[{"en":"We constantly strive to provide the best possible service to our clients.","ko":"우리는 고객들에게 최상의 서비스를 제공하기 위해 끊임없이 노력합니다."}]}]'::jsonb, 26),
('oversee', '/ˌoʊvərˈsiː/', '[{"pos":"동사","definition":"감독하다, 총괄하다","toeic_note":"프로젝트나 직원을 ''총괄 감독''하는 관리자 맥락으로 빈출. supervise와 동의어.","etymology":"Prefix: ''over-''(위에서) + ''see''(보다) -> 위에서 내려다보며 감독함.","synonyms":"supervise(감독하다), manage(관리하다), monitor(감시하다)","examples":[{"en":"She was hired to oversee the entire construction project.","ko":"그녀는 건설 프로젝트 전체를 총괄하기 위해 고용되었습니다."}]}]'::jsonb, 27),
('intrigue', '/ɪnˈtriːɡ/', '[{"pos":"동사","definition":"흥미를 돋우다, 호기심을 자극하다","toeic_note":"광고·기사에서 독자의 흥미를 끄는 맥락. ''be intrigued by(~에 흥미를 느끼다)'' 형태 주의.","etymology":"Root: Latin ''intricare''(얽히게 하다) -> 마음을 얽어매어 호기심을 자극함.","synonyms":"fascinate(매혹하다), captivate(사로잡다)","examples":[{"en":"The mysterious advertisement intrigued many customers.","ko":"그 신비로운 광고는 많은 고객의 호기심을 자극했습니다."}]},{"pos":"명사","definition":"음모, 모의","toeic_note":"비즈니스보다는 이야기·드라마 지문에 등장.","etymology":"동사 intrigue에서 파생 -> 얽히고설킨 책략.","synonyms":"scheme(계략), plot(음모), conspiracy(공모)","examples":[{"en":"The novel is full of political intrigue.","ko":"그 소설은 정치적 음모로 가득합니다."}]}]'::jsonb, 28),
('cover letter', '/ˈkʌvər ˌletər/', '[{"pos":"명사","definition":"자기소개서 (이력서에 동봉하는 편지)","toeic_note":"채용 지문 단골. resume(이력서)와 함께 제출하는 서류.","etymology":"''cover''(동봉하다) + ''letter''(편지) -> 이력서에 곁들여 보내는 편지.","synonyms":"application letter(지원서)","examples":[{"en":"Please attach a cover letter along with your resume.","ko":"이력서와 함께 자기소개서를 첨부해 주세요."}]}]'::jsonb, 29),
('merge', '/mɜːrdʒ/', '[{"pos":"동사","definition":"합병하다, 합치다, 융합되다","toeic_note":"기업 ''merge(합병)''의 명사형은 merger. ''merge with/into'' 전치사 주의.","etymology":"Root: Latin ''mergere''(담그다, 가라앉히다) -> 하나로 잠겨 섞임.","synonyms":"combine(결합하다), consolidate(통합하다), unite(연합하다)","examples":[{"en":"The two companies decided to merge into a single firm.","ko":"두 회사는 하나의 회사로 합병하기로 결정했습니다."}]}]'::jsonb, 30),
('specification', '/ˌspesɪfɪˈkeɪʃn/', '[{"pos":"명사","definition":"규격, 사양, 명세서","toeic_note":"제품·계약 지문에서 ''technical specifications(기술 사양)'', 줄여서 specs로 자주 등장.","etymology":"''specify''(명시하다) + ''-ation'' -> 분명히 명시한 것. (Latin ''specere'' 보다)","synonyms":"requirement(요건), standard(표준), detail(세부사항)","examples":[{"en":"The product must meet all the technical specifications.","ko":"그 제품은 모든 기술 규격을 충족해야 합니다."}]}]'::jsonb, 31),
('comply with', '/kəmˈplaɪ wɪð/', '[{"pos":"동사구","definition":"~을 따르다, 준수하다","toeic_note":"규정·법규 준수 맥락. ''comply with regulations/policy''. 전치사 with 필수.","etymology":"Root: Latin ''complere''(채우다) -> 요구를 채워 응하다. (complete와 같은 뿌리)","synonyms":"follow(따르다), obey(준수하다), adhere to(고수하다), conform to(순응하다)","examples":[{"en":"All employees must comply with the new safety rules.","ko":"모든 직원은 새로운 안전 규칙을 준수해야 합니다."}]}]'::jsonb, 32),
('interpersonal', '/ˌɪntərˈpɜːrsənl/', '[{"pos":"형용사","definition":"대인관계의, 사람 사이의","toeic_note":"채용 공고 자질 요건 단골: ''strong interpersonal skills(뛰어난 대인관계 능력)''.","etymology":"Prefix: ''inter-''(사이) + ''personal''(개인의) -> 사람들 사이의.","synonyms":"relational(관계의), social(사회적인)","examples":[{"en":"Good interpersonal skills are essential for this position.","ko":"이 직책에는 뛰어난 대인관계 능력이 필수적입니다."}]}]'::jsonb, 33),
('remote', '/rɪˈmoʊt/', '[{"pos":"형용사","definition":"원격의, 먼 거리의","toeic_note":"코로나 이후 ''remote work(원격 근무)'' 빈출.","etymology":"Root: Latin ''removere''(re- 뒤로 + movere 움직이다) -> 멀리 옮겨진.","synonyms":"distant(먼), faraway(멀리 떨어진)","examples":[{"en":"Many employees now work from remote locations.","ko":"많은 직원이 이제 원격지에서 근무합니다."}]},{"pos":"형용사","definition":"외딴, 외진","toeic_note":"여행·장소 묘사에서 ''접근하기 어려운 외진 곳''.","etymology":"위와 동일 -> 멀리 떨어져 외진.","synonyms":"isolated(고립된), secluded(외딴)","examples":[{"en":"The resort is located in a remote mountain village.","ko":"그 리조트는 외딴 산골 마을에 위치해 있습니다."}]}]'::jsonb, 34),
('amenable', '/əˈmiːnəbl/', '[{"pos":"형용사","definition":"(충고·제안을) 잘 받아들이는, 순응하는","toeic_note":"''amenable to + 명사(~을 기꺼이 받아들이는)'' 형태로 출제.","etymology":"Root: Latin ''minare''(몰다, 이끌다) -> 이끄는 대로 잘 따르는.","synonyms":"agreeable(선뜻 동의하는), receptive(잘 받아들이는), cooperative(협조적인)","examples":[{"en":"The manager was amenable to our suggestions.","ko":"그 관리자는 우리의 제안을 기꺼이 받아들였습니다."}]}]'::jsonb, 35),
('get through to', '/ɡet ˈθruː tə/', '[{"pos":"동사구","definition":"~와 연락이 닿다; ~를 이해시키다","toeic_note":"전화 통화 맥락에서 ''연락이 닿다''. 회화 지문 빈출.","etymology":"''get''(이르다) + ''through''(통과해) + ''to''(~에게) -> 막힘을 뚫고 ~에게 닿음.","synonyms":"reach(연락하다), contact(연락하다)","examples":[{"en":"I tried to call the office, but I couldn''t get through to anyone.","ko":"사무실에 전화했지만 아무와도 연락이 닿지 않았습니다."}]}]'::jsonb, 36),
('archaeologist', '/ˌɑːrkiˈɑːlədʒɪst/', '[{"pos":"명사","definition":"고고학자","toeic_note":"박물관·역사 관련 지문. archaeology(고고학)를 연구하는 사람.","etymology":"Greek ''arkhaios''(고대의) + ''logos''(학문) + ''-ist''(사람) -> 고대를 연구하는 사람.","synonyms":"excavator(발굴자)","examples":[{"en":"The archaeologist discovered ancient pottery at the site.","ko":"그 고고학자는 그 유적지에서 고대 도자기를 발견했습니다."}]}]'::jsonb, 37),
('relic', '/ˈrelɪk/', '[{"pos":"명사","definition":"유물, 유적","toeic_note":"역사·박물관 지문. ''ancient relics(고대 유물)''.","etymology":"Root: Latin ''relinquere''(뒤에 남기다) -> 뒤에 남겨진 것.","synonyms":"artifact(인공 유물), remains(유물·잔해)","examples":[{"en":"The museum displays relics from the Roman Empire.","ko":"그 박물관은 로마 제국의 유물을 전시합니다."}]}]'::jsonb, 38),
('unearth', '/ʌnˈɜːrθ/', '[{"pos":"동사","definition":"발굴하다, 파내다; (정보·사실을) 밝혀내다","toeic_note":"유물 발굴 + 비유적으로 ''숨은 사실을 밝혀내다''.","etymology":"Prefix: ''un-''(제거) + ''earth''(흙) -> 흙을 걷어내 파냄.","synonyms":"excavate(발굴하다), dig up(파내다), uncover(밝혀내다)","examples":[{"en":"Researchers unearthed important documents in the archive.","ko":"연구원들은 기록 보관소에서 중요한 문서를 찾아냈습니다."}]}]'::jsonb, 39),
('pottery', '/ˈpɑːtəri/', '[{"pos":"명사","definition":"도자기, 도예","toeic_note":"공예·취미 강좌나 박물관 지문. ''pottery class(도예 수업)''.","etymology":"''pot''(항아리) + ''-ery''(제작·장소) -> 항아리류를 만드는 것.","synonyms":"ceramics(도자기), earthenware(토기)","examples":[{"en":"She signed up for a pottery class at the community center.","ko":"그녀는 주민 센터의 도예 수업에 등록했습니다."}]}]'::jsonb, 40),
('stumble upon', '/ˈstʌmbl əˌpɑːn/', '[{"pos":"동사구","definition":"~을 우연히 발견하다, 우연히 마주치다","toeic_note":"''우연히''의 뉘앙스. stumble on과 동일.","etymology":"''stumble''(발이 걸리다) + ''upon''(위에) -> 걷다 발이 걸리듯 우연히 마주침.","synonyms":"come across(우연히 만나다), chance upon(우연히 발견하다)","examples":[{"en":"I stumbled upon an old photo while cleaning the attic.","ko":"다락방을 청소하다가 오래된 사진을 우연히 발견했습니다."}]}]'::jsonb, 41),
('well', '/wel/', '[{"pos":"명사","definition":"우물, 유정(油井)","toeic_note":"기본 단어지만 명사 ''우물'' 의미 주의. ''oil well(유정)''.","etymology":"Old English ''wella''(샘) -> 물이 솟는 곳.","synonyms":"spring(샘), borehole(시추공)","examples":[{"en":"Villagers drew water from the well every morning.","ko":"마을 사람들은 매일 아침 우물에서 물을 길었습니다."}]},{"pos":"부사","definition":"잘, 훌륭하게","toeic_note":"''as well as(~뿐만 아니라)'', ''well-known(잘 알려진)'' 등 복합 표현 빈출.","etymology":"Old English ''wel'' -> 만족스럽게.","synonyms":"skillfully(능숙하게), properly(제대로)","examples":[{"en":"The team performed well under pressure.","ko":"그 팀은 압박 속에서도 잘 해냈습니다."}]},{"pos":"형용사","definition":"건강한, 몸이 좋은","toeic_note":"안부 표현 ''get well(회복하다)''.","etymology":"부사 well에서 확장 -> 상태가 좋은.","synonyms":"healthy(건강한), fine(괜찮은)","examples":[{"en":"I hope you feel well again soon.","ko":"곧 다시 건강해지길 바랍니다."}]}]'::jsonb, 42),
('spot', '/spɑːt/', '[{"pos":"동사","definition":"발견하다, 알아채다, 포착하다","toeic_note":"''찾아내다''의 동사. ''spot an error(오류를 발견하다)''.","etymology":"Middle Dutch ''spotte''(얼룩) -> 눈에 띄는 점 -> 눈에 띄어 알아챔.","synonyms":"detect(감지하다), notice(알아차리다), identify(식별하다)","examples":[{"en":"The inspector spotted a defect in the product.","ko":"검사관은 제품에서 결함을 발견했습니다."}]},{"pos":"명사","definition":"장소, 지점; 점, 얼룩","toeic_note":"''a popular spot(인기 장소)'', ''parking spot(주차 자리)''.","etymology":"위와 동일 -> 특정 지점이나 자국.","synonyms":"location(장소), place(곳), mark(자국)","examples":[{"en":"This is a popular spot for tourists.","ko":"이곳은 관광객에게 인기 있는 장소입니다."}]}]'::jsonb, 43),
('delicate', '/ˈdelɪkət/', '[{"pos":"형용사","definition":"연약한, 깨지기 쉬운; 섬세한","toeic_note":"배송·취급 주의 맥락. ''delicate items(깨지기 쉬운 물품)''. fragile과 유사.","etymology":"Root: Latin ''delicatus''(부드러운, 기쁨을 주는) -> 부드럽고 연약한.","synonyms":"fragile(깨지기 쉬운), fine(섬세한), subtle(미묘한)","examples":[{"en":"Please handle these delicate glasses with care.","ko":"이 깨지기 쉬운 유리잔들을 조심해서 다뤄 주세요."}]},{"pos":"형용사","definition":"(상황이) 미묘한, 다루기 까다로운","toeic_note":"협상·관계 묘사에서 ''a delicate situation(미묘한 상황)''.","etymology":"위와 동일 -> 조심스럽게 다뤄야 하는.","synonyms":"sensitive(민감한), tricky(까다로운)","examples":[{"en":"The negotiation reached a delicate stage.","ko":"그 협상은 미묘한 단계에 이르렀습니다."}]}]'::jsonb, 44),
('glimpse', '/ɡlɪmps/', '[{"pos":"명사","definition":"언뜻 봄, 흘긋 봄","toeic_note":"''catch a glimpse of(~을 언뜻 보다)'' 관용구.","etymology":"Middle English ''glimsen''(희미하게 빛나다) -> 잠깐 스치듯 봄.","synonyms":"glance(흘긋 봄), peek(엿봄)","examples":[{"en":"I caught a glimpse of the famous actor at the airport.","ko":"공항에서 그 유명 배우를 언뜻 보았습니다."}]},{"pos":"동사","definition":"언뜻 보다, 흘긋 보다","toeic_note":"동사로도 쓰임. 명사 형태가 더 빈출.","etymology":"명사 glimpse에서 동사로 확장.","synonyms":"glance at(흘긋 보다), spot(발견하다)","examples":[{"en":"She glimpsed the ocean from the train window.","ko":"그녀는 기차 창문으로 바다를 언뜻 보았습니다."}]}]'::jsonb, 45),
('inclined', '/ɪnˈklaɪnd/', '[{"pos":"형용사","definition":"~하고 싶은, ~하는 경향이 있는","toeic_note":"''be inclined to + 동사원형(~하는 경향이 있다, ~하고 싶다)'' 패턴 빈출.","etymology":"Root: Latin ''inclinare''(in- 쪽으로 + clinare 기울다) -> 마음이 ~쪽으로 기움.","synonyms":"disposed(~하는 경향이 있는), prone(~하기 쉬운), willing(기꺼이 ~하는)","examples":[{"en":"I am inclined to accept their offer.","ko":"나는 그들의 제안을 받아들이고 싶습니다."}]},{"pos":"형용사","definition":"경사진, 기울어진","toeic_note":"물리적 경사 의미. ''an inclined surface(경사면)''.","etymology":"위와 동일 -> 물리적으로 기운.","synonyms":"sloping(비탈진), tilted(기울어진)","examples":[{"en":"The path was steeply inclined.","ko":"그 길은 가파르게 경사져 있었습니다."}]}]'::jsonb, 46),
('accommodate', '/əˈkɑːmədeɪt/', '[{"pos":"동사","definition":"수용하다, ~을 수용할 공간이 있다","toeic_note":"''호텔·시설이 ~명을 수용하다''. ''accommodate up to 200 guests''. 철자(c 2개, m 2개) 주의.","etymology":"Root: Latin ''accommodare''(ad- ~에 + commodus 알맞은) -> ~에 알맞게 맞춤.","synonyms":"house(수용하다), hold(수용하다), seat(앉히다)","examples":[{"en":"The conference hall can accommodate up to 500 people.","ko":"그 회의장은 최대 500명을 수용할 수 있습니다."}]},{"pos":"동사","definition":"(요구·편의를) 들어주다, 부응하다","toeic_note":"고객 응대 맥락. ''accommodate a request(요청을 들어주다)''.","etymology":"위와 동일 -> 상대에 맞춰 줌.","synonyms":"oblige(들어주다), adapt to(맞추다)","examples":[{"en":"We will try to accommodate your special requests.","ko":"귀하의 특별 요청을 들어드리도록 노력하겠습니다."}]}]'::jsonb, 47),
('informative', '/ɪnˈfɔːrmətɪv/', '[{"pos":"형용사","definition":"유익한, 정보를 주는","toeic_note":"강연·자료 후기 단골: ''an informative seminar(유익한 세미나)''.","etymology":"''inform''(알리다) + ''-ative'' -> 정보를 주는.","synonyms":"instructive(교육적인), enlightening(깨우쳐 주는), useful(유용한)","examples":[{"en":"The seminar was very informative and well organized.","ko":"그 세미나는 매우 유익하고 잘 구성되어 있었습니다."}]}]'::jsonb, 48),
('contemplate', '/ˈkɑːntəmpleɪt/', '[{"pos":"동사","definition":"심사숙고하다, 깊이 생각하다; 고려하다","toeic_note":"''contemplate + -ing(~할 것을 고려하다)''. consider보다 격식체.","etymology":"Root: Latin ''contemplari''(com- 강조 + templum 관측 구역) -> 주의 깊게 살핌.","synonyms":"consider(고려하다), ponder(숙고하다), reflect on(되새기다)","examples":[{"en":"The board is contemplating expanding into new markets.","ko":"이사회는 신규 시장 진출을 고려하고 있습니다."}]}]'::jsonb, 49),
('steward', '/ˈstuːərd/', '[{"pos":"명사","definition":"관리인, (재산·시설의) 책임 관리자","toeic_note":"자원·재정을 책임 관리하는 사람. ''stewardship(관리 책임)''도 함께 등장.","etymology":"Old English ''stigweard''(stig 집·홀 + weard 지키는 사람) -> 집을 지키는 사람.","synonyms":"caretaker(관리인), custodian(관리인), administrator(관리자)","examples":[{"en":"He acted as a steward of the company''s finances.","ko":"그는 회사 재정의 관리인 역할을 했습니다."}]},{"pos":"명사","definition":"(비행기·배의) 승무원","toeic_note":"교통·여행 지문. flight attendant와 유사.","etymology":"위와 동일 -> 탈것 안을 돌보는 사람.","synonyms":"attendant(승무원), flight attendant(승무원)","examples":[{"en":"The steward served drinks to the passengers.","ko":"승무원은 승객들에게 음료를 제공했습니다."}]}]'::jsonb, 50);
